const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'F(x)=F0(1−x/h)' },
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: 'F' },
      { kind: 'text', payload: 'h/2' },
      { kind: 'text', payload: 'h' },
      { kind: 'text', payload: 'F0' },
      { kind: 'text', payload: '阴影面积 W = (3/8)F0h = 0.375F0h' },
      { kind: 'text', payload: 'W/(F0h) = 3/8 = 0.375' }
    ];
  },
  render: function (input, metrics) {
    var ox = 70;
    var oy = 330;
    var xh = 510;
    var yF0 = 90;
    var xhalf = (ox + xh) / 2;
    var yhalf = (oy + yF0) / 2;

    var xAxis = visualSdk.arrow(ox, oy, 545, oy, {});
    var fAxis = visualSdk.arrow(ox, oy, ox, 65, {});
    var fn = visualSdk.polyline([[ox, yF0], [xh, oy]]);
    var shade = visualSdk.polyline([[ox, oy], [ox, yF0], [xhalf, yhalf], [xhalf, oy]]);
    shade.push('Z');
    var guide = visualSdk.polyline([[xhalf, yhalf], [xhalf, oy]]);
    var tickHalf = visualSdk.polyline([[xhalf, oy - 5], [xhalf, oy + 5]]);
    var tickH = visualSdk.polyline([[xh, oy - 5], [xh, oy + 5]]);
    var dot = visualSdk.circle(xhalf, yhalf, 4);

    var paths = [
      { id: 'xAxis', commands: xAxis },
      { id: 'fAxis', commands: fAxis },
      { id: 'fn', commands: fn },
      { id: 'shade', commands: shade },
      { id: 'guide', commands: guide },
      { id: 'tickHalf', commands: tickHalf },
      { id: 'tickH', commands: tickH },
      { id: 'dot', commands: dot }
    ];

    var labels = [
      { type: 'label', text: 'F(x)=F0(1−x/h)', x: 350, y: 70, fontSize: 16, fill: '#26354a' },
      { type: 'label', text: 'x', x: 552, y: 350, fontSize: 16, fill: '#26354a' },
      { type: 'label', text: 'F', x: 45, y: 72, fontSize: 16, fill: '#26354a' },
      { type: 'label', text: 'h/2', x: xhalf, y: oy + 24, fontSize: 14, fill: '#26354a', anchor: 'middle' },
      { type: 'label', text: 'h', x: xh, y: oy + 24, fontSize: 14, fill: '#26354a', anchor: 'middle' },
      { type: 'label', text: 'F0', x: ox - 24, y: yF0 + 5, fontSize: 14, fill: '#26354a' },
      { type: 'label', text: '阴影面积 W = (3/8)F0h = 0.375F0h', x: 330, y: 120, fontSize: 15, fill: '#1f4e79' },
      { type: 'label', text: 'W/(F0h) = 3/8 = 0.375', x: 330, y: 142, fontSize: 15, fill: '#1f4e79' }
    ];

    var children = [
      { type: 'path', pathId: 'xAxis', stroke: '#26354a', fill: 'none' },
      { type: 'path', pathId: 'fAxis', stroke: '#26354a', fill: 'none' },
      { type: 'path', pathId: 'shade', stroke: 'none', fill: '#9ab7d3', opacity: 0.55 },
      { type: 'path', pathId: 'fn', stroke: '#1f4e79', fill: 'none', strokeWidth: 2 },
      { type: 'path', pathId: 'guide', stroke: '#5b7fa6', fill: 'none', strokeDasharray: '4 3' },
      { type: 'path', pathId: 'tickHalf', stroke: '#26354a', fill: 'none' },
      { type: 'path', pathId: 'tickH', stroke: '#26354a', fill: 'none' },
      { type: 'path', pathId: 'dot', stroke: '#1f4e79', fill: '#1f4e79' }
    ];
    for (var i = 0; i < labels.length; i++) {
      children.push(labels[i]);
    }

    return {
      schemaVersion: 1,
      sceneId: 'fig-Fx-area',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: input.viewport.widthDu, height: input.viewport.heightDu },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
